let improved = 0;
let untouched = 0;
for (let s = 61; s <= 80; s++) {
  const path = `content/gre/vocab/set-${s}.json`;
  const list = JSON.parse(readFileSync(path, "utf8"));
  let changed = false;
  for (const v of list) {
    const cur = CURATED[v.word.toLowerCase()];
    if (cur) {
      v.definition = cur.d;
      v.synonyms = cur.s;
      v.antonyms = cur.a;
      v.example = cur.e;
      improved++;
      changed = true;
    } else {
      untouched++;
    }
  }
  if (changed) {
    writeFileSync(path, JSON.stringify(list, null, 1));
  }
}
console.log(`improved: ${improved}, untouched: ${untouched}`);